const values = [3, 11, 39, 29, 4, 16, 5, 24];
const kept = values.filter((value) => value < 16);
const largest = Math.max(...kept);
const path = [largest];
let current = largest;
while (true) {
  if (values.includes(current)) {
    path.push(current);
    break;
  }
  current = values.indexOf(current);
}
return path.join(" -> ");
```

